CREATE TABLE "Lotes" (
                         "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                         "ProductoId" integer NOT NULL,
                         "Codigo" character varying(30) NOT NULL,
                         "FechaFabricacion" timestamp with time zone,
                         "FechaVencimiento" timestamp with time zone,
                         "Cantidad" integer NOT NULL,
                         "Estado" character varying(20) NOT NULL,
                         CONSTRAINT "PK_Lotes" PRIMARY KEY ("Id"),
                         CONSTRAINT "FK_Lotes_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
                         CONSTRAINT "CK_Lotes_Cantidad" CHECK ("Cantidad" BETWEEN 1 AND 1000000),
                         CONSTRAINT "CK_Lotes_Estado" CHECK ("Estado" IN ('Disponible', 'Cuarentena', 'Bloqueado'))
);
CREATE UNIQUE INDEX "IX_Lotes_ProductoId_Codigo" ON "Lotes" ("ProductoId", "Codigo");

CREATE TABLE "UnidadesSerie" (
                                 "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                                 "ProductoId" integer NOT NULL,
                                 "LoteId" integer,
                                 "NumeroSerie" character varying(50) NOT NULL,
                                 "Estado" character varying(20) NOT NULL,
                                 CONSTRAINT "PK_UnidadesSerie" PRIMARY KEY ("Id"),
                                 CONSTRAINT "FK_UnidadesSerie_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
                                 CONSTRAINT "FK_UnidadesSerie_Lotes_LoteId" FOREIGN KEY ("LoteId") REFERENCES "Lotes" ("Id") ON DELETE RESTRICT,
                                 CONSTRAINT "CK_UnidadesSerie_Estado" CHECK ("Estado" IN ('Disponible', 'Asignada', 'Baja'))
);
CREATE UNIQUE INDEX "IX_UnidadesSerie_ProductoId_NumeroSerie" ON "UnidadesSerie" ("ProductoId", "NumeroSerie");
CREATE INDEX "IX_UnidadesSerie_LoteId" ON "UnidadesSerie" ("LoteId");